-- ==============================================================================
-- CEBAS Database Migration: 016_seed_400_posts_20_accounts.sql
-- Seeds 400 realistic, authentic posts (20 posts for each of 20 existing accounts)
-- Strictly uses existing user UUIDs in cebas_db without creating any new users.
-- Deterministic keyset-friendly UUIDv7s and realistically staggered timestamps.
-- ==============================================================================

ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, like_count = EXCLUDED.like_count;

-- Synchronize reply_count with actual active rows in post_replies
UPDATE posts p
SET reply_count = (
    SELECT COUNT(*) FROM post_replies pr
    WHERE pr.post_id = p.id AND pr.is_deleted = FALSE
);